/*
    MeowPrinterEncoder

    Turns 1-bit images into the packets of the cheap Bluetooth Low Energy "cat"
    printers, sold as Meow printers, models GB01, GB02, GB03, GT01, MX05, MX06
    and MX10. The protocol is not published by the manufacturers, the details
    come from NaitLee's Cat-Printer project, whose printer_lib/commander.py is
    the reference implementation, and from rbaron's catprinter for the run
    length encoded rows.

    Every command is one packet:

        51 78  cmd  00  lenL lenH  payload...  crc8  FF

    The CRC8 is computed over the payload only, with the standard table for
    polynomial 0x07 and initial value 0.

    The printer buffer is small, so a driver has to pace its writes. That is why
    `encode()` returns a list of packets instead of one buffer: the driver packs
    as many whole packets as fit into one write and never splits one.
*/

/* The commands of the protocol */

const Commands = {
  /* Get device state, also the first command of a print  A3, payload 00      */
  getState: 0xa3,

  /* Update device                                        A9, payload 00      */
  updateDevice: 0xa9,

  /* Set the resolution                                   A4, payload 32 is 200 dpi */
  setDpi: 0xa4,

  /* Print speed                                          BD, one byte        */
  setSpeed: 0xbd,

  /* Energy, the darkness                                 AF, two bytes, LE   */
  setEnergy: 0xaf,

  /* Apply the energy that was set                        BE, payload 01      */
  applyEnergy: 0xbe,

  /* Lattice, begins and ends a print                     A6, eleven bytes    */
  lattice: 0xa6,

  /* One bitmap row of 384 dots                           A2, 48 bytes        */
  drawBitmap: 0xa2,

  /* One run length encoded bitmap row                    BF, one byte per run */
  drawCompressed: 0xbf,

  /* Feed the paper                                       A1, two bytes, LE   */
  feedPaper: 0xa1,
};

/* The fixed payloads of the commands that always carry the same bytes */

const Payloads = {
  getState: [0x00],
  updateDevice: [0x00],
  dpi200: [0x32],
  applyEnergy: [0x01],

  /* Lattice start, begin a print */
  latticeStart: [0xaa, 0x55, 0x17, 0x38, 0x44, 0x5f, 0x5f, 0x5f, 0x44, 0x38, 0x2c],

  /* Lattice end, finish a print */
  latticeEnd: [0xaa, 0x55, 0x17, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x17],
};

/* The bytes around a packet. The header is a fixed magic of two bytes, the byte
   behind the command is always zero, and every packet ends with 0xff */

const Framing = {
  magic: [0x51, 0x78],
  pad: 0x00,
  end: 0xff,
};

/* The flow control packets the printer sends on the notify characteristic. A
   driver stops writing on a pause and continues on a resume */

const FlowControl = {
  pause: [0x51, 0x78, 0xae, 0x01, 0x01, 0x00, 0x10, 0x70, 0xff],
  resume: [0x51, 0x78, 0xae, 0x01, 0x01, 0x00, 0x00, 0x00, 0xff],
};

/* The defaults of the settings a print job opens with. The speed and the energy
   are the two values that decide whether the output is readable */

const Defaults = {
  /* the print head is 384 dots wide */
  width: 384,

  /* a middle of the road print speed */
  speed: 0x20,

  /* 12000, the darkness of the reference implementation */
  energy: 0x2ee0,

  /* rows of the final feed, so the paper clears the head */
  feed: 96,
};

/* A table with the reverse of every byte. The images are most significant bit
   first, the printer takes the least significant bit as the leftmost dot */

const Reversed = new Uint8Array(256);

for (let i = 0; i < 256; i++) {
  let value = 0;

  for (let bit = 0; bit < 8; bit++) {
    value = (value << 1) | ((i >> bit) & 0x01);
  }

  Reversed[i] = value;
}

/* The table of the CRC8 with polynomial 0x07 and initial value 0 */

const CrcTable = new Uint8Array(256);

for (let i = 0; i < 256; i++) {
  let crc = i;

  for (let bit = 0; bit < 8; bit++) {
    crc = (crc & 0x80) ? ((crc << 1) ^ 0x07) & 0xff : (crc << 1) & 0xff;
  }

  CrcTable[i] = crc;
}

/**
 * A 1-bit image. One bit per pixel, most significant bit first, every row
 * padded to a whole number of bytes, a set bit is a black dot. This is the
 * image format of ReceiptPrinterRenderer.
 *
 * @typedef {object} Bitmap
 * @property {number} width      Width in dots
 * @property {number} height     Height in dots
 * @property {Uint8Array} data   Packed rows, Math.ceil(width / 8) bytes per row
 */

/**
 * A rendered segment of the receipt
 *
 * @typedef {object} ImageItem
 * @property {'image'} type
 * @property {number} width      Width in dots
 * @property {number} height     Height in dots
 * @property {Uint8Array} data   Packed rows, Math.ceil(width / 8) bytes per row
 */

/**
 * Advance the paper without printing
 *
 * @typedef {object} FeedItem
 * @property {'feed'} type
 * @property {number} [height]   Number of blank dot rows
 */

/**
 * One item of the stream this encoder accepts. Anything else, such as the cut
 * and pulse items of a printer with a cutter or a drawer, is ignored.
 *
 * @typedef {ImageItem | FeedItem | {type: string}} EncodeItem
 */

/**
 * One row, in whichever of the two row formats is the shorter one
 *
 * @typedef {object} EncodedRow
 * @property {number} command                 The command byte, A2 raw or BF compressed
 * @property {Uint8Array | number[]} payload  The bytes of the row
 */

/**
 * How the printer prints
 *
 * @typedef {object} MeowPrinterEncoderOptions
 * @property {number} [width]      Width of the print head in dots, a multiple of eight, 384 by default
 * @property {number} [energy]     The darkness, up to 0xffff, 12000 by default
 * @property {number} [speed]      The print speed, one byte, 0x20 by default
 * @property {number} [feed]       Dot rows of the feed at the end of a job, 96 by default
 * @property {boolean} [compress]  Whether rows may be run length encoded, true by default
 */

/**
 * Encodes images for the cheap Bluetooth Low Energy cat printers
 */
class MeowPrinterEncoder {
  /* The flow control packets of the protocol, so that a driver can recognise
     them on the notify characteristic without knowing the bytes */

  static PAUSE = new Uint8Array(FlowControl.pause);
  static RESUME = new Uint8Array(FlowControl.resume);

  #width;
  #stride;
  #speed;
  #energy;
  #feed;
  #compress;

  /**
   * Create an encoder
   *
   * @param  {MeowPrinterEncoderOptions}  [options]   How the printer prints
   */
  constructor(options) {
    const settings = options || {};

    this.#width = clamp(settings.width, Defaults.width, 8, 0xffff);
    this.#speed = clamp(settings.speed, Defaults.speed, 0, 0xff);
    this.#energy = clamp(settings.energy, Defaults.energy, 0, 0xffff);
    this.#feed = clamp(settings.feed, Defaults.feed, 0, 0xffff);

    /* Run length encoded rows can be switched off, for a printer that does not
       accept them */

    this.#compress = settings.compress !== false;

    if (this.#width % 8 != 0) {
      throw new Error('The width of the print area must be a multiple of eight dots, not ' + this.#width);
    }

    this.#stride = this.#width / 8;
  }

  /**
   * The width of the print head in dots
   *
   * @return {number}   The width this encoder pads its rows to
   */
  get width() {
    return this.#width;
  }

  /**
   * Encode a list of items as the packets of a complete print job
   *
   * Items are the output of a renderer: image and feed. The printer has no
   * cutter and no drawer, so cut and pulse items are ignored. The result is a
   * list of packets, one per command, because a driver sends one packet per
   * Bluetooth write.
   *
   * @param  {EncodeItem[]}  items   The items of the job
   * @return {Uint8Array[]}          One packet per command, the whole job
   */
  encode(items) {
    const packets = [];

    /*
      Job start. The state of the device is asked for first, the way the
      reference implementation opens a print, then the settings, and the
      lattice command that begins the print.
    */

    packets.push(MeowPrinterEncoder.packet(Commands.getState, Payloads.getState));
    packets.push(MeowPrinterEncoder.packet(Commands.setDpi, Payloads.dpi200));
    packets.push(MeowPrinterEncoder.packet(Commands.setSpeed, [this.#speed]));
    packets.push(MeowPrinterEncoder.packet(Commands.setEnergy, [this.#energy & 0xff, this.#energy >> 8]));
    packets.push(MeowPrinterEncoder.packet(Commands.applyEnergy, Payloads.applyEnergy));
    packets.push(MeowPrinterEncoder.packet(Commands.updateDevice, Payloads.updateDevice));
    packets.push(MeowPrinterEncoder.packet(Commands.lattice, Payloads.latticeStart));

    for (const item of items || []) {
      switch (item.type) {
        /* One packet per row, padded to the print width, compressed when that helps */

        case 'image':
          this.#image(packets, /** @type {ImageItem} */ (item));
          break;

          /* Advance the paper without sending white rows, which is slow on this link */

        case 'feed': {
          const height = clamp(/** @type {FeedItem} */ (item).height, 0, 0, 0xffff);

          packets.push(MeowPrinterEncoder.packet(Commands.feedPaper, [height & 0xff, height >> 8]));
          break;
        }

        /*
          The printer has no cutter and no drawer, so cut and pulse are never
          in the supported commands of a renderer. They are ignored here as
          well, in case a caller builds its own item list.
        */
      }
    }

    /*
      Job end. The lattice command finishes the print, and the paper is fed so
      that the last printed row leaves the print head and can be torn off.
    */

    packets.push(MeowPrinterEncoder.packet(Commands.lattice, Payloads.latticeEnd));
    packets.push(MeowPrinterEncoder.packet(Commands.feedPaper, [this.#feed & 0xff, this.#feed >> 8]));

    return packets;
  }

  /**
   * Encode one image as the packets of a complete print job
   *
   * @param  {Bitmap}        bitmap   The image to print
   * @return {Uint8Array[]}           One packet per command, the whole job
   */
  encodeImage(bitmap) {
    return this.encode([{
      type: 'image',
      width: bitmap.width,
      height: bitmap.height,
      data: bitmap.data,
    }]);
  }

  /**
   * Append the row packets of one image item
   *
   * @param  {Uint8Array[]}  packets   The packets of the job so far
   * @param  {ImageItem}     item      The image item
   */
  #image(packets, item) {
    /*
      A renderer is constructed with the width of the print head, so it never
      produces a wider image. A caller that builds its own item list could, and
      the dots that fall off the paper would be silently lost.
    */

    if (item.width > this.#width) {
      throw new Error(
          'An image item of ' + item.width + ' dots is wider than the print head of ' + this.#width + ' dots',
      );
    }

    const source = Math.ceil(item.width / 8);

    for (let y = 0; y < item.height; y++) {
      const row = new Uint8Array(this.#stride);

      for (let x = 0; x < source; x++) {
        row[x] = item.data[y * source + x] || 0x00;
      }

      const encoded = this.#compress ?
        MeowPrinterEncoder.encodeRow(row) :
        {command: Commands.drawBitmap, payload: Array.from(row, MeowPrinterEncoder.reverseBits)};

      packets.push(MeowPrinterEncoder.packet(encoded.command, encoded.payload));
    }
  }

  /**
   * Build one packet around a command and its payload
   *
   * @param  {number}                     command   The command byte
   * @param  {Uint8Array | number[]}      payload   The bytes of the payload
   * @return {Uint8Array}                           The complete packet
   */
  static packet(command, payload) {
    const length = payload.length;
    const result = new Uint8Array(length + 8);

    result[0] = Framing.magic[0];
    result[1] = Framing.magic[1];
    result[2] = command;
    result[3] = Framing.pad;
    result[4] = length & 0xff;
    result[5] = length >> 8;

    result.set(payload, 6);

    result[length + 6] = MeowPrinterEncoder.crc8(payload);
    result[length + 7] = Framing.end;

    return result;
  }

  /**
   * Compute the CRC8 of a payload, polynomial 0x07 and initial value 0
   *
   * @param  {Uint8Array | number[]}   bytes   The bytes to compute the checksum over
   * @return {number}                          The checksum
   */
  static crc8(bytes) {
    let crc = 0;

    for (let i = 0; i < bytes.length; i++) {
      crc = CrcTable[(crc ^ bytes[i]) & 0xff];
    }

    return crc;
  }

  /**
   * Reverse the bits of a byte, so that the printer draws them left to right
   *
   * @param  {number}   value   The byte
   * @return {number}           The byte with its bits in the opposite order
   */
  static reverseBits(value) {
    return Reversed[value & 0xff];
  }

  /**
   * Encode one row as runs of equal dots
   *
   * One byte is a run: bit 7 is the value of the dots, 1 is black, and bits 0
   * to 6 are the length of the run, 1 to 127. A run that is longer is split
   * into several bytes of the same value. The runs cover the row from the
   * leftmost dot to the rightmost, and together they add up to the full width
   * of the row, because that is what the printer draws.
   *
   * A run byte carries no bitmap, so unlike the raw row there is nothing to
   * reverse: the runs are simply in the order the dots are printed.
   *
   * @param  {Uint8Array}   row   The row, most significant bit first, the leftmost dot first
   * @return {number[]}           One byte per run, value in bit 7 and length in bits 0 to 6
   */
  static runLengthEncode(row) {
    const result = [];
    let value = -1;
    let run = 0;

    for (let i = 0; i < row.length * 8; i++) {
      const dot = (row[i >> 3] >> (7 - (i & 0x07))) & 0x01;

      if (dot == value) {
        run++;
        continue;
      }

      if (run > 0) {
        appendRun(result, run, value);
      }

      value = dot;
      run = 1;
    }

    if (run > 0) {
      appendRun(result, run, value);
    }

    return result;
  }

  /**
   * Encode one row in the shortest of the two row formats
   *
   * A row of text compresses to a fraction of the bitmap it replaces, a
   * dithered photograph or a row of alternating dots does not compress at all
   * and is sent raw. The choice is per row, and it is the choice of the
   * reference implementation, which keeps the runs when they are exactly as
   * long as the bitmap.
   *
   * @param  {Uint8Array}   row   The row, most significant bit first, the full print width
   * @return {EncodedRow}         The command byte and the payload of the row packet
   */
  static encodeRow(row) {
    const compressed = MeowPrinterEncoder.runLengthEncode(row);

    if (compressed.length <= row.length) {
      return {command: Commands.drawCompressed, payload: compressed};
    }

    const raw = new Uint8Array(row.length);

    for (let i = 0; i < row.length; i++) {
      raw[i] = Reversed[row[i]];
    }

    return {command: Commands.drawBitmap, payload: raw};
  }

  /**
   * Whether a notification is the packet that asks the driver to stop writing
   *
   * @param  {DataView | Uint8Array | number[]}   bytes   The bytes of the notification
   * @return {boolean}                                    Whether it is the pause packet
   */
  static isPause(bytes) {
    return matches(bytes, FlowControl.pause);
  }

  /**
   * Whether a notification is the packet that says the printer has room again
   *
   * @param  {DataView | Uint8Array | number[]}   bytes   The bytes of the notification
   * @return {boolean}                                    Whether it is the resume packet
   */
  static isResume(bytes) {
    return matches(bytes, FlowControl.resume);
  }
}

/**
 * Append one run to an encoded row, split over several bytes when it is longer
 * than 127
 *
 * @param  {number[]}   result   The bytes of the encoded row so far
 * @param  {number}     run      The length of the run, in dots
 * @param  {number}     value    The value of the dots, 1 is black
 */
function appendRun(result, run, value) {
  while (run > 0x7f) {
    result.push(0x7f | (value << 7));
    run -= 0x7f;
  }

  if (run > 0) {
    result.push((value << 7) | run);
  }
}

/**
 * Compare a notification with a known packet
 *
 * A notification arrives as a DataView on the web Bluetooth API, and as a typed
 * array or a plain array everywhere else, so all three are accepted.
 *
 * @param  {DataView | Uint8Array | number[]}   bytes    The bytes of the notification
 * @param  {number[]}                           packet   The bytes of the packet to compare it with
 * @return {boolean}                                     Whether the notification is that packet
 */
function matches(bytes, packet) {
  if (!bytes) {
    return false;
  }

  const view = bytes instanceof DataView ?
    new Uint8Array(bytes.buffer, bytes.byteOffset, bytes.byteLength) :
    bytes;

  if (view.length != packet.length) {
    return false;
  }

  for (let i = 0; i < packet.length; i++) {
    if (view[i] != packet[i]) {
      return false;
    }
  }

  return true;
}

/**
 * Clamp a value that goes on the wire, so that a missing or absurd option or
 * item property cannot produce a packet the printer will choke on
 *
 * @param  {number | undefined}   value      The value, which may be anything at all
 * @param  {number}               fallback   The value to use when there is none
 * @param  {number}               min        The lowest value of the field
 * @param  {number}               max        The highest value of the field
 * @return {number}                          A whole number within the range
 */
function clamp(value, fallback, min, max) {
  if (typeof value != 'number' || !Number.isFinite(value)) {
    value = fallback;
  }

  return Math.min(max, Math.max(min, Math.round(value)));
}

export { MeowPrinterEncoder, MeowPrinterEncoder as default };
